import React, { useState } from 'react';

const Landing = () => {
  const [investment, setInvestment] = useState(0);
  const [sales, setSales] = useState([{ name: '', purchasePrice: 0, salePrice: 0 }]);
  const [rentals, setRentals] = useState([{ name: '', rentalPrice: 0, rentalCount: 0 }]);
  const [expenses, setExpenses] = useState([{ name: '', amount: 0 }]);
  const [result, setResult] = useState('');

  const handleAddSale = () => {
    setSales([...sales, { name: '', purchasePrice: 0, salePrice: 0 }]);
  };

  const handleAddRental = () => {
    setRentals([...rentals, { name: '', rentalPrice: 0, rentalCount: 0 }]);
  };

  const handleAddExpense = () => {
    setExpenses([...expenses, { name: '', amount: 0 }]);
  };

  const calculateProfitLoss = () => {
    const salesProfit = sales.reduce(
      (acc, sale) => acc + (sale.salePrice - sale.purchasePrice),
      0
    );

    const rentalIncome = rentals.reduce(
      (acc, rental) => acc + rental.rentalPrice * rental.rentalCount,
      0
    );

    const totalExpenses = expenses.reduce((acc, expense) => acc + expense.amount, 0);

    const totalProfit = salesProfit + rentalIncome - investment - totalExpenses;

    setResult(
      totalProfit >= 0
        ? `You made a profit of $${totalProfit.toFixed(2)}`
        : `You incurred a loss of $${Math.abs(totalProfit).toFixed(2)}`
    );
  };

  return (
    <div className="container mt-5">
      <h1 className="text-center">Money Management App</h1>
      <p className="text-center">
        Calculate your profit or loss based on your investments, sales, rentals, and expenses.
      </p>

      {/* Investment Input */}
      <div className="mt-4">
        <h3>Investment</h3>
        <div className="form-group">
          <label>Enter your total investment amount:</label>
          <input
            type="number"
            className="form-control"
            value={investment}
            onChange={(e) => setInvestment(parseFloat(e.target.value) || 0)}
            placeholder="Investment amount"
          />
        </div>
      </div>

      {/* Sales Input */}
      <div className="mt-4">
        <h3>Sales</h3>
        {sales.map((sale, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={sale.name}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].name = e.target.value;
                setSales(newSales);
              }}
              placeholder="Item name"
            />
            <input
              type="number"
              className="form-control mb-2"
              value={sale.purchasePrice}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].purchasePrice = parseFloat(e.target.value) || 0;
                setSales(newSales);
              }}
              placeholder="Purchase price"
            />
            <input
              type="number"
              className="form-control"
              value={sale.salePrice}
              onChange={(e) => {
                const newSales = [...sales];
                newSales[index].salePrice = parseFloat(e.target.value) || 0;
                setSales(newSales);
              }}
              placeholder="Sale price"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddSale}>
          Add Another Sale
        </button>
      </div>

      {/* Rentals Input */}
      <div className="mt-4">
        <h3>Rentals</h3>
        {rentals.map((rental, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={rental.name}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].name = e.target.value;
                setRentals(newRentals);
              }}
              placeholder="Toy name"
            />
            <input
              type="number"
              className="form-control mb-2"
              value={rental.rentalPrice}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].rentalPrice = parseFloat(e.target.value) || 0;
                setRentals(newRentals);
              }}
              placeholder="Rental price"
            />
            <input
              type="number"
              className="form-control"
              value={rental.rentalCount}
              onChange={(e) => {
                const newRentals = [...rentals];
                newRentals[index].rentalCount = parseFloat(e.target.value) || 0;
                setRentals(newRentals);
              }}
              placeholder="Number of rentals"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddRental}>
          Add Another Rental
        </button>
      </div>

      {/* Expenses Input */}
      <div className="mt-4">
        <h3>Expenses</h3>
        {expenses.map((expense, index) => (
          <div key={index} className="mb-3">
            <input
              type="text"
              className="form-control mb-2"
              value={expense.name}
              onChange={(e) => {
                const newExpenses = [...expenses];
                newExpenses[index].name = e.target.value;
                setExpenses(newExpenses);
              }}
              placeholder="Expense name"
            />
            <input
              type="number"
              className="form-control"
              value={expense.amount}
              onChange={(e) => {
                const newExpenses = [...expenses];
                newExpenses[index].amount = parseFloat(e.target.value) || 0;
                setExpenses(newExpenses);
              }}
              placeholder="Expense amount"
            />
          </div>
        ))}
        <button className="btn btn-secondary" onClick={handleAddExpense}>
          Add Another Expense
        </button>
      </div>

      {/* Calculate Button */}
      <div className="mt-4">
        <button className="btn btn-primary" onClick={calculateProfitLoss}>
          Calculate Profit/Loss
        </button>
      </div>

      {/* Result */}
      <div className="mt-4">
        <h3>Result</h3>
        <p className="font-weight-bold">{result}</p>
      </div>
    </div>
  );
};

export default Landing;
